tools/shift_joint_candidates.py:
"""Enumerate identifiable small-tree shift locations and optimum equalities.

No likelihood or score formula is duplicated here. Branch IDs are NWKIT's
level-order IDs, including zero for the baseline optimum.
"""

import itertools
import math

from nwkit.util import assign_branch_ids


def set_partitions(values):
    if not values:
        yield ()
        return
    first, *rest = values
    for groups in set_partitions(rest):
        yield ((first,), *groups)
        for index, group in enumerate(groups):
            yield (*groups[:index], (first, *group), *groups[index + 1 :])


def canonical_groups(groups):
    return tuple(sorted(tuple(sorted(group)) for group in groups))


def tip_groups(tree, selected, groups=None):
    ids = assign_branch_ids(tree)
    aliases = (
        {branch: branch for branch in (0, *selected)}
        if groups is None
        else {branch: min(group) for group in groups for branch in group}
    )
    labels, tips = {}, {}
    for node in tree.traverse("preorder"):
        labels[node] = aliases[ids[node]] if ids[node] in aliases else labels[node.up]
        if node.is_leaf:
            tips.setdefault(labels[node], []).append(node.name)
    return tuple(sorted(tuple(sorted(names)) for names in tips.values()))


def has_redundant_change(tree, selected, groups):
    ids = assign_branch_ids(tree)
    aliases = {branch: min(group) for group in groups for branch in group}
    labels = {}
    for node in tree.traverse("preorder"):
        if node.is_root:
            labels[node] = aliases[0]
            continue
        labels[node] = aliases[ids[node]] if ids[node] in selected else labels[node.up]
        if ids[node] in selected and labels[node] == labels[node.up]:
            return True
    return False


def enumerate_candidates(tree, max_shifts=2, limit=5000):
    if max_shifts not in (0, 1, 2) or limit < 1:
        raise ValueError(
            "Joint reference supports 0..2 shifts and a positive candidate limit"
        )
    nodes = list(tree.traverse())
    if len(list(tree.leaves())) > 16:
        raise ValueError("Joint reference is limited to at most 16 tips")
    if any(len(node.children) != 2 for node in nodes if not node.is_leaf):
        raise ValueError("Joint reference requires a fully bifurcating tree")
    if any(
        not math.isfinite(node.dist) or node.dist <= 0
        for node in nodes
        if not node.is_root
    ):
        raise ValueError("Joint reference requires finite positive branches")
    heights = [tree.get_distance(tree, tip) for tip in tree.leaves()]
    if max(heights) - min(heights) > max(heights) * 1e-8:
        raise ValueError("Joint reference requires an ultrametric tree")
    ids = assign_branch_ids(tree)
    branches = sorted(branch for branch in ids.values() if branch)
    candidates = []
    counts = {
        "configurations_considered": 0,
        "unidentifiable_configurations": 0,
        "redundant_equalities": 0,
    }
    for size in range(max_shifts + 1):
        for selected in itertools.combinations(branches, size):
            counts["configurations_considered"] += 1
            # Empty ancestral regimes cause rank-deficient unconstrained designs.
            # With <=2 shifts this removes the pair of root-child edges.
            if len(tip_groups(tree, selected)) != size + 1:
                counts["unidentifiable_configurations"] += 1
                continue
            for groups in sorted(
                canonical_groups(p) for p in set_partitions((0, *selected))
            ):
                if has_redundant_change(tree, selected, groups):
                    counts["redundant_equalities"] += 1
                    continue
                candidates.append(
                    {
                        "candidate_id": len(candidates),
                        "shift_branch_ids": list(selected),
                        "groups": [list(group) for group in groups],
                    }
                )
                if len(candidates) > limit:
                    raise ValueError("Joint candidate limit exceeded before fitting")
    return candidates, counts

tools/shift_simulation_cases.py:
"""Independent branchwise OU generator and truth-based selection metrics."""

import math

import numpy as np
from scipy.stats import binomtest

from nwkit.util import assign_branch_ids, read_tree

SCENARIOS = ("null", "single", "distinct", "convergent")


def partition(labels):
    groups = {}
    for name, label in labels.items():
        groups.setdefault(label, []).append(name)
    return sorted(sorted(group) for group in groups.values())


def balanced_newick(tips):
    if tips < 8 or tips & (tips - 1):
        raise ValueError("tips must be a power of two >= 8")
    nodes = [f"t{i}:1" for i in range(tips)]
    while len(nodes) > 1:
        nodes = [f"({nodes[i]},{nodes[i + 1]}):1" for i in range(0, len(nodes), 2)]
    return nodes[0][:-2] + ";"


def simulate(*, tips, scenario, root_model, se, effect, seed, alpha=0.7, sigma2=0.25):
    """Draw innovations directly; no fitted model or backend simulation is used."""
    if scenario not in SCENARIOS or root_model not in ("OUfixedRoot", "OUrandomRoot"):
        raise ValueError("Unknown simulation scenario or root treatment")
    if (
        not all(math.isfinite(x) for x in (se, effect, alpha, sigma2))
        or min(alpha, sigma2, effect) <= 0
        or se < 0
    ):
        raise ValueError("Invalid generating parameters")
    newick = balanced_newick(tips)
    tree = read_tree(newick, "auto", True, quiet=True)
    ids = assign_branch_ids(tree)
    quarter = tips // 4
    targets = [
        set(f"t{i}" for i in range(start, start + quarter)) for start in (0, tips // 2)
    ]
    shifts = {}
    for node in tree.traverse():
        clade = set(node.leaf_names())
        if scenario != "null" and clade == targets[0]:
            shifts[node] = effect
        if scenario in ("distinct", "convergent") and clade == targets[1]:
            shifts[node] = -effect if scenario == "distinct" else effect
    rng = np.random.default_rng(seed)
    root_var = sigma2 / (2 * alpha) if root_model == "OUrandomRoot" else 0.0
    states, means, optima, regimes = (
        {tree: rng.normal(0, math.sqrt(root_var))},
        {tree: 0.0},
        {tree: 0.0},
        {tree: 0},
    )
    # Innovation loadings provide an independent exact covariance for generator QA.
    loadings = {tree: np.eye(1, len(ids), ids[tree]).ravel() * math.sqrt(root_var)}
    for node in tree.traverse("preorder"):
        if node.is_root:
            continue
        optima[node] = shifts.get(node, optima[node.up])
        regimes[node] = ids[node] if node in shifts else regimes[node.up]
        decay = math.exp(-alpha * node.dist)
        sd = math.sqrt(sigma2 * (-math.expm1(-2 * alpha * node.dist)) / (2 * alpha))
        offset = (1 - decay) * optima[node]
        states[node] = decay * states[node.up] + offset + rng.normal(0, sd)
        means[node] = decay * means[node.up] + offset
        loadings[node] = decay * loadings[node.up]
        loadings[node][ids[node]] += sd
    leaves = list(tree.leaves())
    matrix = np.asarray([loadings[node] for node in leaves])
    observations = [states[node] + rng.normal(0, se) for node in leaves]
    truth = {
        "seed": seed,
        "scenario": scenario,
        "tips": tips,
        "root_model": root_model,
        "standard_error": se,
        "effect": effect,
        "alpha": alpha,
        "sigma2": sigma2,
        "shift_branch_ids": sorted(ids[node] for node in shifts),
        "shift_optima": {str(ids[node]): value for node, value in shifts.items()},
        "tip_names": [node.name for node in leaves],
        "observations": observations,
        "tip_mean": {node.name: means[node] for node in leaves},
        "tip_optimum": {node.name: optima[node] for node in leaves},
        "ancestry_partition": partition({node.name: regimes[node] for node in leaves}),
        "shared_partition": partition({node.name: optima[node] for node in leaves}),
        "covariance": (matrix @ matrix.T + se**2 * np.eye(tips)).tolist(),
    }
    return newick, truth


def selection_metrics(model, truth):
    tips = model["tip_predictions"]
    parents = {row["branch_id"]: row["parent"] for row in model["branches"]}
    selected = set(model["shift_branch_ids"])
    ancestry = {}
    for row in tips:
        branch = row["branch_id"]
        while branch != 0 and branch not in selected:
            branch = parents[branch]
        ancestry[row["leaf_name"]] = branch
    result = {
        "selected_shifts": len(selected),
        "any_shift": bool(selected),
        "exact_edges": sorted(selected) == truth["shift_branch_ids"],
        "ancestry_recovered": partition(ancestry) == truth["ancestry_partition"],
        "shared_recovered": model["parameters"]["alpha"] > 0
        and partition({row["leaf_name"]: row["regime"] for row in tips})
        == truth["shared_partition"],
        "tip_mean_rmse": float(
            np.sqrt(
                np.mean(
                    [
                        (row["predicted"] - truth["tip_mean"][row["leaf_name"]]) ** 2
                        for row in tips
                    ]
                )
            )
        ),
        "alpha": model["parameters"]["alpha"],
        "any_merge": bool(model["convergence"] and model["convergence"]["merges"]),
        "backend_version": model["backend_version"],
    }
    boot = model.get("bootstrap")
    if boot:
        result.update(
            {
                f"bootstrap_{key}": boot[key]
                for key in ("attempted", "successful", "failed")
            }
        )
        for field, target in (
            ("tip_partition_frequencies", "ancestry_partition"),
            ("shared_optimum_partition_frequencies", "shared_partition"),
        ):
            if field in boot:
                result[f"bootstrap_truth_{target}_frequency"] = sum(
                    row["frequency"]
                    for row in boot[field]
                    if row["groups"] == truth[target]
                )
    return result


def rate(count, denominator):
    if not denominator:
        return {"count": count, "denominator": 0, "rate": None, "wilson_95": None}
    ci = binomtest(count, denominator).proportion_ci(method="wilson")
    return {
        "count": count,
        "denominator": denominator,
        "rate": count / denominator,
        "wilson_95": [ci.low, ci.high],
    }


def summarize(rows):
    good = [row for row in rows if row["status"] == "completed"]
    result = {
        "attempted": len(rows),
        "completed": len(good),
        "failure": rate(len(rows) - len(good), len(rows)),
    }
    for key in (
        "any_shift",
        "any_merge",
        "exact_edges",
        "ancestry_recovered",
        "shared_recovered",
    ):
        count = sum(row[key] for row in good)
        result[key] = rate(count, len(good))
        if key.endswith("recovered") or key == "exact_edges":
            result[f"{key}_returned"] = rate(count, len(rows))
    result["mean_tip_mean_rmse"] = (
        float(np.mean([row["tip_mean_rmse"] for row in good])) if good else None
    )
    result["bootstrap_counts"] = {
        key: sum(row.get(f"bootstrap_{key}", 0) for row in good)
        for key in ("attempted", "successful", "failed")
    }
    for key in ("ancestry_partition", "shared_partition"):
        values = [
            row[f"bootstrap_truth_{key}_frequency"]
            for row in good
            if f"bootstrap_truth_{key}_frequency" in row
        ]
        result[f"bootstrap_truth_{key}"] = {
            "outer_fits_available": len(values),
            "mean_frequency": float(np.mean(values)) if values else None,
        }
    return result

nwkit/shift.py:
"""Validate shift inputs and map external fit clades to NWKIT branch IDs."""

import hashlib
import json
import math
import shutil
import sys
import tempfile
from pathlib import Path
from typing import Any

import pandas as pd

from nwkit import __version__
from nwkit.file_paths import validate_outputs_do_not_replace_inputs
from nwkit.output_transaction import output_transaction, validate_output_targets
from nwkit.rooting_state import require_rooted
from nwkit.shift_backend import run_backend
from nwkit.shift_bootstrap import collect_bootstrap
from nwkit.shift_convergence import collect_convergence, shared_regime_rows
from nwkit.shift_math import ancestral_effect_scales, observation_variances
from nwkit.shift_results import (
    align_regime_optima,
    collect_effects,
    collect_search,
    collect_tips,
    summarize_effects,
)
from nwkit.util import (
    assign_branch_ids,
    read_tip_table,
    read_tree,
    validate_unique_named_leaves,
)


def _validate_options(args):
    if args.convergence and args.criterion not in {"AICc", "BIC", "pBIC"}:
        raise ValueError("--convergence supports only AICc, BIC and pBIC criteria.")
    if not 0 <= args.bootstrap <= 2147483647:
        raise ValueError("--bootstrap must be between 0 and 2147483647.")
    if not 0 <= args.bootstrap_seed <= 2147483647:
        raise ValueError("--bootstrap-seed must be between 0 and 2147483647.")
    if args.max_shifts < 0 or not 1 <= args.exhaustive_max_configurations <= 2147483647:
        raise ValueError(
            "--max-shifts must be non-negative and --exhaustive-max-configurations between 1 and 2147483647."
        )
    if not 0 <= args.seed <= 2147483647:
        raise ValueError("--seed must be between 0 and 2147483647.")


def _prepare(args):
    _validate_options(args)
    tree = read_tree(
        args.infile, args.format, args.quoted_node_names, rooted=args.input_rooted
    )
    require_rooted(tree, "Shift inference requires a rooted tree.")
    validate_unique_named_leaves(tree, "--infile")
    ids = assign_branch_ids(tree)
    distances = {tree: 0.0}
    for node in tree.traverse("preorder"):
        if not node.is_leaf and len(node.children) != 2:
            raise ValueError(
                "Initial shift inference requires a strictly bifurcating tree."
            )
        if not node.is_root:
            if node.dist is None or not math.isfinite(node.dist) or node.dist <= 0:
                raise ValueError(
                    "Shift inference requires finite, positive non-root branch lengths."
                )
            distances[node] = distances[node.up] + node.dist
    leaves = list(tree.leaves())
    heights = [distances[node] for node in leaves]
    if len(leaves) < 3 or not all(math.isfinite(x) for x in heights):
        raise ValueError(
            "Shift inference requires at least three tips and finite tree height."
        )
    if max(heights) - min(heights) > max(heights) * 1e-8:
        raise ValueError(
            "Shift inference requires an ultrametric tree; no automatic repair is performed."
        )
    if args.max_shifts >= len(leaves) - 1:
        raise ValueError(
            "--max-shifts must be smaller than the number of tips minus one."
        )
    if args.state_column == "leaf_name":
        raise ValueError("--state-column must differ from leaf_name.")
    if args.standard_error_column == "":
        raise ValueError("--standard-error-column requires a nonempty column name.")
    if args.standard_error_column in {"leaf_name", args.state_column}:
        raise ValueError(
            "--standard-error-column must differ from leaf_name and --state-column."
        )
    table, _, _ = read_tip_table(
        args.trait,
        tree_leaf_names=[n.name for n in leaves],
        required_columns=[args.state_column]
        + ([args.standard_error_column] if args.standard_error_column else []),
        unmatched="error",
    )
    values = pd.to_numeric(
        table.set_index("leaf_name")[args.state_column], errors="raise"
    )
    if values.isna().any() or not all(math.isfinite(float(x)) for x in values):
        raise ValueError(
            "Initial shift inference requires a finite observation for every tip."
        )
    if values.nunique() < 2:
        raise ValueError("Shift inference requires a non-invariant trait.")
    tokens = {node: f"t{i}" for i, node in enumerate(leaves)}
    clades: dict[Any, list[str]] = {}
    newicks: dict[Any, str] = {}
    for node in tree.traverse("postorder"):
        clades[node] = (
            [tokens[node]]
            if node.is_leaf
            else sorted(t for child in node.children for t in clades[child])
        )
        label = (
            tokens[node]
            if node.is_leaf
            else "(" + ",".join(newicks[c] for c in node.children) + ")"
        )
        newicks[node] = label + (";" if node.is_root else f":{node.dist:.17g}")
    data = pd.DataFrame(
        {
            "leaf_name": [tokens[n] for n in leaves],
            "value": [float(values[n.name]) for n in leaves],
        }
    )
    if args.standard_error_column:
        errors = pd.to_numeric(
            table.set_index("leaf_name")[args.standard_error_column], errors="raise"
        )
        if errors.isna().any():
            raise ValueError("A finite standard error is required for every tip.")
        data["standard_error"] = [float(errors[n.name]) for n in leaves]
        data["observation_variance"] = observation_variances(data.standard_error)
    mapping = {"/".join(clades[node]): ids[node] for node in ids}
    return tree, ids, tokens, mapping, newicks[tree], data


def _configuration(value, mapping):
    keys = value.split(";") if value else []
    if len(keys) != len(set(keys)) or any(
        key not in mapping or mapping[key] == 0 for key in keys
    ):
        raise ValueError("kfl1ou returned an invalid shift clade configuration.")
    return sorted(mapping[key] for key in keys)


def _metrics(path):
    model = pd.read_csv(path, sep="\t", dtype=str, keep_default_na=False)
    if len(model) != 1:
        raise ValueError("Expected one kfl1ou model.")
    metrics = {
        key: float(model.iloc[0][key])
        for key in ("alpha", "sigma2", "intercept", "log_likelihood", "score")
    }
    if (
        not all(math.isfinite(x) for x in metrics.values())
        or metrics["alpha"] < 0
        or metrics["sigma2"] <= 0
    ):
        raise ValueError("kfl1ou returned invalid model parameters or scores.")
    return metrics, str(model.iloc[0]["backend_version"])


def _collect(directory, mapping, convergence=False):
    shifts = pd.read_csv(directory / "shifts.tsv", sep="\t", keep_default_na=False)
    if list(shifts.columns) != ["clade", "mean_effect", "optimum_effect"]:
        raise ValueError("Invalid kfl1ou shifts table.")
    selected = _configuration(";".join(shifts.clade), mapping)
    metrics, version = _metrics(directory / "model.tsv")
    search_metrics = (
        _metrics(directory / "unconstrained-model.tsv")[0] if convergence else metrics
    )
    candidates = []
    for row in pd.read_csv(
        directory / "candidates.tsv", sep="\t", keep_default_na=False
    ).itertuples():
        score = float(row.score)
        candidates.append(
            {
                "score": score if math.isfinite(score) else None,
                "shift_branch_ids": _configuration(row.clades, mapping),
            }
        )
    if not any(
        c["shift_branch_ids"] == selected
        and c["score"] is not None
        and math.isclose(
            c["score"], search_metrics["score"], rel_tol=1e-10, abs_tol=1e-10
        )
        for c in candidates
    ):
        raise ValueError("Selected kfl1ou model is missing from its candidate profile.")
    return selected, metrics, version, candidates, search_metrics


def shift_main(args):
    tables_out = {
        "effects": args.effects_out,
        "regimes": args.regime_parameters_out,
        "tips": args.tip_summary_out,
    }
    outputs = (
        [args.model_out]
        + ([args.fit_out] if args.fit_out else [])
        + [p for p in tables_out.values() if p]
    )
    if any(path == "-" for path in outputs):
        raise ValueError("Auxiliary shift outputs require file paths.")
    if args.outfile != "-":
        outputs.append(args.outfile)
    targets = validate_output_targets(outputs)
    if any(not Path(target).parent.is_dir() for target in targets.values()):
        raise ValueError("Output parent directories must exist before inference.")
    validate_outputs_do_not_replace_inputs(
        [
            ("--infile", args.infile),
            ("--trait", args.trait),
            ("--rscript", shutil.which(args.rscript)),
        ],
        [(path, path) for path in outputs],
    )
    tree, ids, tokens, mapping, newick, data = _prepare(args)
    with tempfile.TemporaryDirectory(prefix="nwkit-shift-") as temporary:
        directory = Path(temporary)
        (directory / "tree.nwk").write_text(newick, encoding="utf-8")
        trait_text = data.to_csv(sep="\t", index=False)
        (directory / "trait.tsv").write_text(trait_text, encoding="utf-8")
        execution = run_backend(directory, args)
        selected, metrics, version, candidates, search_metrics = _collect(
            directory, mapping, args.convergence
        )
        convergence, aliases = collect_convergence(
            directory, mapping, selected, args.convergence
        )
        if args.convergence and metrics["alpha"] <= 0:
            raise ValueError("Convergence requires identifiable OU optima (alpha > 0).")
        regimes: dict[Any, str] = {}
        for node in tree.traverse("preorder"):
            regimes[node] = (
                "baseline"
                if node.is_root
                else (aliases[ids[node]] if ids[node] in selected else regimes[node.up])
            )
        rows = [{"branch_id": ids[n], "regime": regimes[n]} for n in ids]
        result = (
            pd.DataFrame(rows).sort_values("branch_id").to_csv(sep="\t", index=False)
        )
        if metrics["alpha"] == 0 and args.root_model == "OUrandomRoot":
            raise ValueError(
                "Stationary/random-root OU is undefined at alpha=0; an explicit fixed-root model is required."
            )
        effects = collect_effects(directory, mapping, selected)
        shift_rows, regime_rows, optima = summarize_effects(
            tree, ids, regimes, metrics, effects
        )
        if args.convergence:
            scales = ancestral_effect_scales(
                tree, ids, metrics["intercept"], effects, "optimum_effect"
            )
            regime_rows = shared_regime_rows(
                regime_rows,
                {ids[node]: scale for node, scale in scales.items()},
            )
        tip_rows = collect_tips(
            directory, tokens, ids, regimes, data, metrics, effects, optima
        )
        align_regime_optima(regime_rows, tip_rows)
        search = collect_search(directory, search_metrics, tree)
        tables = {"effects": shift_rows, "regimes": regime_rows, "tips": tip_rows}
        model = {
            "schema_version": 5,
            "convergence": convergence,
            "unconstrained_parameters": search_metrics if args.convergence else None,
            "search_stage": "unconstrained_shift_discovery",
            "bootstrap": collect_bootstrap(directory, args, tree, ids, mapping),
            "standard_error_column": args.standard_error_column,
            "effective_observation_error": "known_independent_variances"
            if "observation_variance" in data and data.observation_variance.gt(0).any()
            else "none",
            "observation_error": "known_independent_variances"
            if args.standard_error_column
            else "none",
            "optimum_convention": "root_mean_equals_baseline_optimum",
            "effective_root_model": args.root_model,
            "shift_effects": shift_rows,
            "regime_parameters": regime_rows,
            "tip_predictions": tip_rows,
            "search": search,
            "nwkit_version": __version__,
            "backend": "kfl1ou",
            "backend_version": version,
            "trait": args.state_column,
            "root_model": args.root_model,
            "criterion": args.criterion,
            "search_strategy": args.search_strategy,
            "max_shifts": args.max_shifts,
            "exhaustive_max_configurations": args.exhaustive_max_configurations,
            "seed": args.seed,
            "time_scale": "original",
            "tree_normalized": False,
            "convergence_searched": args.convergence,
            "shift_branch_ids": selected,
            "parameters": metrics,
            "candidates": candidates,
            "tip_tokens": {token: node.name for node, token in tokens.items()},
            "analysis_tree_tokens": newick,
            "analysis_input_sha256": hashlib.sha256(
                (newick + "\n" + trait_text).encode()
            ).hexdigest(),
            "branches": [
                {
                    "branch_id": ids[n],
                    "parent": -1 if n.is_root else ids[n.up],
                    "name": n.name,
                    "dist": None if n.is_root else n.dist,
                    "regime": regimes[n],
                }
                for n in ids
            ],
            "search_diagnostics_r": (directory / "diagnostics.txt").read_text(
                encoding="utf-8"
            ),
            "execution": execution,
            "asr_note": "Regime map only. ASR refits a model; match root treatment, observation-error inputs and units before comparing. Uncertainty conditional on selected regimes excludes selection uncertainty.",
        }
        with output_transaction(outputs) as staged:
            Path(staged[args.model_out]).write_text(
                json.dumps(model, indent=2, ensure_ascii=False, allow_nan=False) + "\n",
                encoding="utf-8",
            )
            for role, path in tables_out.items():
                if path:
                    columns = {
                        "effects": [
                            "branch_id",
                            "regime",
                            "parent_regime",
                            "mean_effect",
                            "optimum_effect",
                            "optimum_identifiable",
                        ],
                        "regimes": [
                            "regime",
                            "branch_id",
                            "optimum",
                            "optimum_identifiable",
                        ],
                        "tips": [
                            "leaf_name",
                            "branch_id",
                            "regime",
                            "standard_error",
                            "observation_variance",
                            "observed",
                            "predicted",
                            "residual",
                            "optimum",
                            "optimum_identifiable",
                        ],
                    }[role]
                    pd.DataFrame(tables[role], columns=columns).to_csv(
                        staged[path], sep="\t", index=False, na_rep="NA"
                    )
            if args.fit_out:
                shutil.copyfile(directory / "fit.rds", staged[args.fit_out])
            if args.outfile != "-":
                Path(staged[args.outfile]).write_text(result, encoding="utf-8")
        if execution.get("stderr"):
            sys.stderr.write(execution["stderr"])
        bootstrap = model["bootstrap"]
        if bootstrap is not None and bootstrap["failed"]:
            sys.stderr.write(
                f"Warning: {bootstrap['failed']}/{bootstrap['attempted']} bootstrap refits failed; "
                "support frequencies use successful refits only. See model JSON for details.\n"
            )
        if args.outfile == "-":
            sys.stdout.write(result)

