"""Validate external bootstrap configurations and summarize selection support."""

import csv
from collections import Counter
from typing import Any


def _table(directory, name, columns):
    with (directory / name).open(encoding="utf-8", newline="") as stream:
        reader = csv.DictReader(stream, delimiter="\t", strict=True)
        if reader.fieldnames != columns:
            raise ValueError(f"Invalid kfl1ou {name} columns.")
        try:
            rows = list(reader)
        except csv.Error as error:
            raise ValueError(f"Invalid kfl1ou {name} quoting.") from error
    if any(None in row or any(v is None for v in row.values()) for row in rows):
        raise ValueError(f"Invalid kfl1ou {name} row.")
    return rows


def _count(value):
    if not value.isascii() or not value.isdecimal():
        raise ValueError("Invalid kfl1ou bootstrap count.")
    return int(value)


def _partition(tree, ids, selected):
    regimes: dict[Any, int] = {}
    groups: dict[int, list[str]] = {}
    for node in tree.traverse("preorder"):
        regimes[node] = (
            ids[node] if node.is_root or ids[node] in selected else regimes[node.up]
        )
        if node.is_leaf:
            groups.setdefault(regimes[node], []).append(node.name)
    return tuple(sorted(tuple(sorted(names)) for names in groups.values()))


def collect_bootstrap(directory, args, tree, ids, mapping):
    """Frequencies are conditional on successful refits; no posterior claims."""
    if args.bootstrap == 0:
        return None
    rows = _table(directory, "bootstrap.tsv", ["attempted", "successful", "failed"])
    if len(rows) != 1:
        raise ValueError("Expected one kfl1ou bootstrap summary.")
    counts = {key: _count(value) for key, value in rows[0].items()}
    if (
        counts["attempted"] != args.bootstrap
        or counts["successful"] < 1
        or counts["successful"] + counts["failed"] != args.bootstrap
    ):
        raise ValueError("Inconsistent kfl1ou bootstrap counts.")
    configurations = []
    for index, row in enumerate(
        _table(directory, "bootstrap-configurations.tsv", ["success_index", "clades"]),
        1,
    ):
        keys = row["clades"].split(";") if row["clades"] else []
        if (
            _count(row["success_index"]) != index
            or len(keys) != len(set(keys))
            or len(keys) > args.max_shifts
            or any(key not in mapping or mapping[key] == 0 for key in keys)
        ):
            raise ValueError("Invalid kfl1ou bootstrap configuration.")
        configurations.append(tuple(sorted(mapping[key] for key in keys)))
    successful = counts["successful"]
    if len(configurations) != successful:
        raise ValueError("Bootstrap configurations disagree with successful count.")
    failures = _table(directory, "bootstrap-failures.tsv", ["message", "count"])
    failure_rows = [
        {"message": row["message"], "count": _count(row["count"])} for row in failures
    ]
    if (
        any(not row["message"] or row["count"] < 1 for row in failure_rows)
        or len({row["message"] for row in failure_rows}) != len(failure_rows)
        or sum(row["count"] for row in failure_rows) > counts["failed"]
    ):
        raise ValueError("Inconsistent kfl1ou bootstrap failure messages.")
    inclusion = Counter(branch for config in configurations for branch in config)
    exact = Counter(configurations)
    partitions = Counter(
        _partition(tree, ids, set(config)) for config in configurations
    )
    result = {
        "type": "parametric",
        "seed": args.bootstrap_seed,
        **counts,
        "frequency_denominator": "successful_refits",
        "failure_messages": failure_rows,
        "failures_without_message": counts["failed"]
        - sum(row["count"] for row in failure_rows),
        "successful_configurations": [list(config) for config in configurations],
        "edge_inclusion": [
            {
                "branch_id": branch,
                "count": inclusion[branch],
                "frequency": inclusion[branch] / successful,
            }
            for branch in sorted(ids.values())
            if branch != 0
        ],
        "configuration_frequencies": [
            {
                "shift_branch_ids": list(config),
                "count": count,
                "frequency": count / successful,
            }
            for config, count in sorted(
                exact.items(), key=lambda item: (-item[1], item[0])
            )
        ],
        "tip_partition_frequencies": [
            {
                "groups": [list(group) for group in partition],
                "count": count,
                "frequency": count / successful,
            }
            for partition, count in sorted(
                partitions.items(), key=lambda item: (-item[1], item[0])
            )
        ],
    }
    if args.convergence:
        from nwkit.shift_convergence import convergence_bootstrap

        result.update(
            convergence_bootstrap(directory, configurations, mapping, tree, ids)
        )
    return result

nwkit/shift_convergence.py:
"""Public R convergence orchestration and validated shared-optimum groups."""

from typing import Any

from nwkit.shift_bootstrap import _table
from nwkit.shift_math import close_in_units

R_CONVERGENCE = r"""
convergence.enabled <- length(args) >= 9L && args[9] == "TRUE"
converge <- function(model) {
    if (!is.finite(model$alpha) || model$alpha <= 0)
        stop("Convergence requires identifiable OU optima (alpha > 0).")
    result <- kfl1ou::estimate_convergent_regimes(
        model, criterion=args[2], method="backward", fixed.alpha=FALSE, nCores=1)
    if (!is.finite(result$alpha) || result$alpha <= 0)
        stop("Convergence refit has unidentifiable OU optima (alpha <= 0).")
    result
}
group_keys <- function(model) {
    if (!identical(model$tree$edge, tr$edge) ||
        !identical(model$tree$tip.label, tr$tip.label))
        stop("Convergence changed tree edge coordinates.")
    vapply(model$convergent.regimes, function(group)
        paste(vapply(group, function(edge)
            if (edge == 0) "@root" else keys[edge], ""), collapse=";"), "")
}
write_model <- function(model, path) write_tsv(data.frame(
    backend_version=as.character(utils::packageVersion("kfl1ou")),
    alpha=model$alpha, sigma2=model$sigma2, intercept=model$intercept,
    log_likelihood=sum(model$logLik), score=model$score), path)
search.fit <- fit
if (convergence.enabled) {
    write_model(search.fit, "unconstrained-model.tsv")
    fit <- converge(search.fit)
    attr(fit, "nwkit.unconstrained.fit") <- search.fit
    write_tsv(data.frame(clades=group_keys(fit)), "convergence.tsv")
}
convergent_bootstrap <- function() {
    simulations <- stats::simulate(fit, nsim=as.integer(args[7]),
        seed=as.integer(args[8]), preserve.missing=TRUE, engine="tree")
    records <- lapply(simulations, function(Ystar) tryCatch({
        initial <- kfl1ou::estimate_shift_configuration(
            tr, Ystar, max.nShifts=as.integer(args[1]), criterion=args[2],
            root.model=args[3], search.strategy=args[4],
            exhaustive.max.configurations=as.integer(args[5]),
            ensemble.seed=as.integer(args[6]), nCores=1, quietly=TRUE,
            input_error=input.error, measurement_error=FALSE)
        refit <- converge(initial)
        list(ok=TRUE, shifts=unname(refit$shift.configuration),
             groups=paste(group_keys(refit), collapse="|"), error="")
    }, error=function(e) list(ok=FALSE, error=conditionMessage(e))))
    good <- vapply(records, function(record) record$ok, logical(1))
    if (!any(good)) stop("all bootstrap replicates failed.")
    errors <- vapply(records[!good], function(record) record$error, "")
    write_tsv(data.frame(success_index=seq_len(sum(good)),
        groups=vapply(records[good], function(record) record$groups, "")),
        "bootstrap-convergence.tsv")
    list(attempted=length(records), successful=sum(good), failed=sum(!good),
         all.shifts=lapply(records[good], function(record) record$shifts),
         failure.messages=table(errors[nzchar(errors)]))
}
"""


def decode_groups(values, mapping, selected):
    groups = []
    for value in values:
        keys = value.split(";")
        if any(key != "@root" and key not in mapping for key in keys):
            raise ValueError("Invalid convergence clade.")
        group = [0 if key == "@root" else mapping[key] for key in keys]
        if any(key != "@root" and mapping[key] == 0 for key in keys):
            raise ValueError(
                "Convergence background requires its explicit root marker."
            )
        groups.append(sorted(group))
    flat = [branch for group in groups for branch in group]
    if len(flat) != len(set(flat)) or set(flat) != {0, *selected}:
        raise ValueError(
            "Convergence groups must partition background and selected shifts."
        )
    return sorted(groups)


def collect_convergence(directory, mapping, selected, enabled):
    if not enabled:
        return None, {branch: f"shift_{branch}" for branch in selected}
    groups = decode_groups(
        [row["clades"] for row in _table(directory, "convergence.tsv", ["clades"])],
        mapping,
        selected,
    )
    aliases = {
        branch: "baseline" if 0 in group else f"shift_{min(group)}"
        for group in groups
        for branch in group
    }
    return {
        "method": "backward",
        "alpha_refitted": True,
        "globally_optimal": False,
        "groups": [
            {"regime": aliases[group[0]], "branch_ids": group} for group in groups
        ],
        "merges": 1 + len(selected) - len(groups),
    }, aliases


def shared_regime_rows(rows, scales):
    unique: dict[str, Any] = {}
    for row in rows:
        previous = unique.get(row["regime"])
        if previous is not None:
            if not close_in_units(
                previous["optimum"],
                row["optimum"],
                operands=(scales[previous["branch_id"]], scales[row["branch_id"]]),
            ):
                raise ValueError("Constrained regime optima disagree.")
            if row["branch_id"] >= previous["branch_id"]:
                continue
        unique[row["regime"]] = row
    return sorted(unique.values(), key=lambda row: row["branch_id"])


def convergence_bootstrap(directory, configurations, mapping, tree, ids):
    from collections import Counter

    rows = _table(directory, "bootstrap-convergence.tsv", ["success_index", "groups"])
    if len(rows) != len(configurations):
        raise ValueError("Convergence bootstrap counts disagree.")
    partitions: Counter[tuple[tuple[str, ...], ...]] = Counter()
    groups_by_replicate = []
    for index, (row, selected) in enumerate(zip(rows, configurations, strict=True), 1):
        if row["success_index"] != str(index):
            raise ValueError("Invalid convergence bootstrap success index.")
        groups = decode_groups(row["groups"].split("|"), mapping, selected)
        groups_by_replicate.append(groups)
        aliases = {branch: min(group) for group in groups for branch in group}
        regimes: dict[Any, int] = {}
        tips: dict[int, list[str]] = {}
        for node in tree.traverse("preorder"):
            regimes[node] = (
                aliases[ids[node]] if ids[node] in aliases else regimes[node.up]
            )
            if node.is_leaf:
                tips.setdefault(regimes[node], []).append(node.name)
        partition = tuple(sorted(tuple(sorted(names)) for names in tips.values()))
        partitions[partition] += 1
    return {
        "selection": "shift_and_convergence",
        "successful_convergence_groups": groups_by_replicate,
        "shared_optimum_partition_frequencies": [
            {
                "groups": [list(group) for group in partition],
                "count": count,
                "frequency": count / len(rows),
            }
            for partition, count in sorted(
                partitions.items(), key=lambda item: (-item[1], item[0])
            )
        ],
    }

nwkit/shift_math.py:
"""Scale-aware checks and branch geometry for OU shift inference."""

import math
from typing import Any


def remaining_heights(tree):
    """Measure time forward to tips without subtracting large root depths."""
    heights: dict[Any, float] = {}
    for node in tree.traverse("postorder"):
        heights[node] = (
            0.0
            if node.is_leaf
            else max(child.dist + heights[child] for child in node.children)
        )
    return heights


def close_in_units(actual, expected, *, operands=(), rtol=1e-7):
    """Allow relative error and rounding of source operands, not a unitful floor."""
    values = (actual, expected, *operands)
    if not all(math.isfinite(x) for x in values):
        return False
    tolerance = 32 * max(math.ulp(float(x)) for x in values)
    return math.isclose(actual, expected, rel_tol=rtol, abs_tol=tolerance)


def ancestral_effect_scales(tree, ids, intercept, effects, field):
    """Source and intermediate magnitudes along each ancestry only."""
    scales: dict[Any, float] = {}
    partial: dict[Any, float] = {}
    for node in tree.traverse("preorder"):
        delta = effects.get(ids[node], {}).get(field)
        partial[node] = intercept if node.is_root else partial[node.up] + (delta or 0.0)
        scales[node] = max(
            abs(intercept) if node.is_root else scales[node.up],
            abs(delta) if delta is not None else 0.0,
            abs(partial[node]),
        )
    return scales


def observation_variances(standard_errors):
    """Square finite nonnegative SEs, rejecting loss of representable variance."""
    values = []
    for error in standard_errors:
        error = float(error)
        if not math.isfinite(error) or error < 0:
            raise ValueError("Standard errors must be finite and non-negative.")
        variance = error * error
        if not math.isfinite(variance) or (error > 0 and variance == 0):
            raise ValueError(
                "A squared standard error is outside floating-point range."
            )
        values.append(variance)
    return values

nwkit/shift_reference.py:
"""Fixed-parameter OU shift evaluation using NWKIT's Gaussian tree engine.

This is a validation evaluator, not a shift search or parameter optimizer.
The baseline uses the explicit convention root mean = baseline optimum.
At alpha=0, finite mean effects are represented as BM mean offsets, not optima.
"""

import math

import numpy as np
from scipy.linalg import cho_factor, cho_solve

from nwkit.gaussian_tree import (
    GaussianRootPrior,
    GaussianTransition,
    GaussianTreeProcess,
    ou_transition,
)
from nwkit.shift_math import observation_variances, remaining_heights


def build_shift_process(tree, *, alpha, sigma2, intercept, mean_effects, root_model):
    if root_model not in {"OUfixedRoot", "OUrandomRoot"}:
        raise ValueError("Unsupported kfl1ou root model.")
    if (
        not all(math.isfinite(x) for x in (alpha, sigma2, intercept))
        or alpha < 0
        or sigma2 <= 0
    ):
        raise ValueError("Shift parameters must be finite, alpha >= 0 and sigma2 > 0.")
    if root_model == "OUrandomRoot" and alpha == 0:
        raise ValueError(
            "Stationary/random-root OU is undefined at alpha=0; use a fixed-root BM model explicitly."
        )
    nodes = set(tree.traverse())
    if (
        tree in mean_effects
        or not set(mean_effects) <= nodes
        or not all(math.isfinite(x) for x in mean_effects.values())
    ):
        raise ValueError("Shift effects must be finite and identify non-root nodes.")
    depths = {tree: 0.0}
    for node in tree.traverse("preorder"):
        if not node.is_root:
            if not math.isfinite(node.dist) or node.dist <= 0:
                raise ValueError("Shift reference requires positive branch lengths.")
            depths[node] = depths[node.up] + node.dist
    heights = [depths[n] for n in tree.leaves()]
    height = max(heights)
    if max(heights) - min(heights) > height * 1e-8:
        raise ValueError("Shift reference requires an ultrametric tree.")
    remaining = remaining_heights(tree)
    root_variance = (
        sigma2 / (2 * alpha) if root_model == "OUrandomRoot" and alpha > 0 else 0.0
    )
    root = GaussianRootPrior(
        "stationary" if root_variance > 0 else "fixed", intercept, root_variance
    )
    optima = {tree: intercept}
    transitions = {}
    for node in tree.traverse("preorder"):
        if node.is_root:
            continue
        if alpha == 0:
            transitions[node] = GaussianTransition(
                1.0, mean_effects.get(node, 0.0), sigma2 * node.dist
            )
        else:
            denominator = -math.expm1(-alpha * remaining[node.up])
            optima[node] = optima[node.up] + mean_effects.get(node, 0.0) / denominator
            transitions[node], _ = ou_transition(node.dist, alpha, sigma2, optima[node])
    return GaussianTreeProcess(tree, transitions, root, "OU-SHIFT", alpha)


def evaluate_shift_model(tree, *, observations, standard_errors=None, **parameters):
    """Return tip mean, covariance and ordinary ML density without refitting.

    Dense covariance is intentional for small validation fixtures. Production
    shift search does not invoke this O(tips**2) reference evaluator.
    """
    process = build_shift_process(tree, **parameters)
    leaves = list(tree.leaves())
    means, _ = process.marginal_moments()
    mean = np.asarray([means[n] for n in leaves])
    covariance = process.covariance(leaves)
    observed = np.asarray(observations, dtype=float)
    if observed.shape != mean.shape or not np.isfinite(observed).all():
        raise ValueError("One finite observation per tip is required.")
    if standard_errors is not None:
        variance = np.asarray(observation_variances(standard_errors))
        if variance.shape != mean.shape:
            raise ValueError("One standard error per tip is required.")
        covariance = covariance + np.diag(variance)
    factor = cho_factor(covariance, lower=True)
    residual = observed - mean
    log_likelihood = -0.5 * (
        len(mean) * math.log(2 * math.pi)
        + 2 * np.log(np.diag(factor[0])).sum()
        + residual @ cho_solve(factor, residual)
    )
    return mean, covariance, float(log_likelihood)

nwkit/shift_results.py:
"""Validated, label-restored shift effects, regime optima and tip predictions."""

import math
from typing import Any

import pandas as pd

from nwkit.shift_math import ancestral_effect_scales, close_in_units, remaining_heights


def _number(value, *, nullable=False):
    if nullable and str(value) == "NA":
        return None
    result = float(value)
    if not math.isfinite(result):
        raise ValueError("Nonfinite value in kfl1ou result.")
    return result


def _table(path, columns):
    table = pd.read_csv(path, sep="\t", keep_default_na=False, dtype=str)
    if list(table.columns) != columns:
        raise ValueError(f"Invalid kfl1ou {path.name} columns.")
    return table


def collect_effects(directory, mapping, selected):
    table = _table(directory / "shifts.tsv", ["clade", "mean_effect", "optimum_effect"])
    effects = {}
    for row in table.itertuples():
        branch = mapping.get(row.clade)
        if branch not in selected or branch in effects:
            raise ValueError("Invalid or duplicated effect clade.")
        effects[branch] = {
            "mean_effect": _number(row.mean_effect),
            "optimum_effect": _number(row.optimum_effect, nullable=True),
        }
    if set(effects) != set(selected):
        raise ValueError("Missing selected shift effects.")
    return effects


def summarize_effects(tree, ids, regimes, metrics, effects):
    alpha = metrics["alpha"]
    heights = remaining_heights(tree)
    baseline = metrics["intercept"] if alpha > 0 else None
    optima = {tree: baseline}
    shifts = []
    regime_rows = [
        {
            "regime": "baseline",
            "branch_id": 0,
            "optimum": baseline,
            "optimum_identifiable": baseline is not None,
        }
    ]
    for node in tree.traverse("preorder"):
        if node.is_root:
            continue
        optima[node] = optima[node.up]
        if ids[node] not in effects:
            continue
        effect = effects[ids[node]]
        delta = effect["optimum_effect"]
        expected = (
            None
            if alpha == 0
            else effect["mean_effect"] / -math.expm1(-alpha * heights[node.up])
        )
        if (expected is None) != (delta is None) or (
            expected is not None and not close_in_units(expected, delta)
        ):
            raise ValueError("kfl1ou mean and optimum shift effects are inconsistent.")
        optimum = (
            None
            if delta is None or optima[node.up] is None
            else optima[node.up] + delta
        )
        optima[node] = optimum
        shifts.append(
            {
                "branch_id": ids[node],
                "regime": regimes[node],
                "parent_regime": regimes[node.up],
                **effect,
                "optimum_identifiable": delta is not None,
            }
        )
        regime_rows.append(
            {
                "regime": regimes[node],
                "branch_id": ids[node],
                "optimum": optimum,
                "optimum_identifiable": optimum is not None,
            }
        )
    return sorted(shifts, key=lambda row: row["branch_id"]), regime_rows, optima


def collect_tips(directory, tokens, ids, regimes, data, metrics, effects, optima):
    table = _table(
        directory / "tips.tsv",
        ["token", "observed", "predicted", "residual", "optimum"],
    )
    by_token = {token: node for node, token in tokens.items()}
    if table.token.duplicated().any() or set(table.token) != set(by_token):
        raise ValueError("kfl1ou tip identities differ from the analysis tree.")
    observed = dict(zip(data.leaf_name, data.value, strict=True))
    errors = (
        dict(zip(data.leaf_name, data.standard_error, strict=True))
        if "standard_error" in data
        else {}
    )
    variances = (
        dict(zip(data.leaf_name, data.observation_variance, strict=True))
        if "observation_variance" in data
        else {}
    )
    expected_mean: dict[Any, float] = {}
    tree = next(iter(tokens)).root
    mean_scales = ancestral_effect_scales(
        tree, ids, metrics["intercept"], effects, "mean_effect"
    )
    optimum_scales = ancestral_effect_scales(
        tree, ids, metrics["intercept"], effects, "optimum_effect"
    )
    for node in tree.traverse("preorder"):
        expected_mean[node] = (
            metrics["intercept"]
            if node.is_root
            else expected_mean[node.up]
            + effects.get(ids[node], {}).get("mean_effect", 0.0)
        )
    rows = []
    for row in table.itertuples():
        node = by_token[row.token]
        values = {
            key: _number(getattr(row, key))
            for key in ("observed", "predicted", "residual")
        }
        if not close_in_units(values["observed"], observed[row.token], rtol=1e-12):
            raise ValueError("kfl1ou observations differ from the input trait values.")
        if not close_in_units(
            values["observed"] - values["predicted"],
            values["residual"],
            operands=(values["observed"], values["predicted"]),
        ) or not close_in_units(
            values["predicted"], expected_mean[node], operands=(mean_scales[node],)
        ):
            raise ValueError(
                "kfl1ou predictions, effects and residuals are inconsistent."
            )
        backend_optimum = _number(row.optimum, nullable=True)
        optimum = optima[node]
        # The BM intercept remains defined, but finite OU optima are not.
        if metrics["alpha"] > 0 and (
            (optimum is None) != (backend_optimum is None)
            or (
                optimum is not None
                and not close_in_units(
                    optimum, backend_optimum, operands=(optimum_scales[node],)
                )
            )
        ):
            raise ValueError("kfl1ou tip and regime optima are inconsistent.")
        rows.append(
            {
                "leaf_name": node.name,
                "branch_id": ids[node],
                "regime": regimes[node],
                "standard_error": errors.get(row.token, 0.0),
                "observation_variance": variances.get(row.token, 0.0),
                **values,
                "optimum": backend_optimum if metrics["alpha"] > 0 else None,
                "optimum_identifiable": optimum is not None,
            }
        )
    return sorted(rows, key=lambda row: row["branch_id"])


def align_regime_optima(regime_rows, tip_rows):
    """Keep directly fitted optima after checking reconstructed shift effects."""
    canonical = {
        row["regime"]: row["optimum"] for row in regime_rows if row["branch_id"] == 0
    }
    for row in tip_rows:
        regime, value = row["regime"], row["optimum"]
        if regime in canonical:
            expected = canonical[regime]
            if (expected is None) != (value is None) or (
                value is not None and not close_in_units(value, expected)
            ):
                raise ValueError("kfl1ou returned different optima for one regime.")
        else:
            canonical[regime] = value
    for row in [*regime_rows, *tip_rows]:
        if row["regime"] in canonical:
            row["optimum"] = canonical[row["regime"]]


def collect_search(directory, metrics, tree):
    columns = [
        "strategy",
        "configuration_space_size",
        "evaluated_configurations",
        "coverage",
        "globally_optimal",
        "ensemble_attempted",
        "ensemble_successful",
        "ensemble_failed",
        "alpha_lower",
        "alpha_upper",
    ]
    table = _table(directory / "search.tsv", columns)
    if len(table) != 1:
        raise ValueError("Expected one search summary.")
    raw = table.iloc[0]
    result = {
        key: _number(raw[key], nullable=True)
        for key in columns
        if key not in {"strategy", "globally_optimal"}
    }
    if raw.globally_optimal not in {"TRUE", "FALSE", "NA"}:
        raise ValueError("Invalid global-optimum diagnostic.")
    result.update(
        strategy=raw.strategy,
        globally_optimal={"TRUE": True, "FALSE": False, "NA": None}[
            raw.globally_optimal
        ],
    )
    _validate_search(result)
    height = remaining_heights(tree)[tree]
    for side in ("lower", "upper"):
        bound = result[f"alpha_{side}"]
        result[f"alpha_at_{side}_bound"] = (
            None
            if bound is None
            else math.isclose(
                metrics["alpha"], bound, rel_tol=1e-6, abs_tol=1e-8 / height
            )
        )
    return result


def _validate_search(result):
    if result["strategy"] not in {"none", "lasso", "ensemble", "exhaustive"}:
        raise ValueError("Unknown effective search strategy.")
    for key in (
        "configuration_space_size",
        "evaluated_configurations",
        "ensemble_attempted",
        "ensemble_successful",
        "ensemble_failed",
    ):
        value = result[key]
        if value is not None and (value < 0 or value != int(value)):
            raise ValueError("Search counts must be non-negative integers.")
    coverage = result["coverage"]
    if coverage is not None and not 0 <= coverage <= 1:
        raise ValueError("Search coverage must be between zero and one.")
    attempted, successful, failed = (
        result[k]
        for k in ("ensemble_attempted", "ensemble_successful", "ensemble_failed")
    )
    if (
        all(v is not None for v in (attempted, successful, failed))
        and attempted != successful + failed
    ):
        raise ValueError("Ensemble success/failure counts do not match attempts.")
    low, high = result["alpha_lower"], result["alpha_upper"]
    if any(v is not None and v < 0 for v in (low, high)) or (
        low is not None and high is not None and low > high
    ):
        raise ValueError("Invalid reported alpha bounds.")
